package net.spell_engine.client.render.paladin;
import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.entity.layers.RenderLayer;import net.minecraft.client.renderer.entity.RenderLayerParent;import net.minecraft.client.renderer.entity.state.AvatarRenderState;import net.minecraft.client.model.player.PlayerModel;import net.minecraft.client.renderer.SubmitNodeCollector;import net.minecraft.client.model.geom.EntityModelSet;import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.renderer.texture.OverlayTexture;import net.paladins.client.entity.*;import net.spell_engine.internals.*;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.neoforge.client.event.EntityRenderersEvent;
/** Native banner artwork, attached to the animated body exactly like worn equipment. */
@EventBusSubscriber(modid="spell_engine",value=Dist.CLIENT)
public final class BackBannerLayer extends RenderLayer<AvatarRenderState,PlayerModel>{
 private final BattleBannerEntityModel banner;
 public BackBannerLayer(RenderLayerParent<AvatarRenderState,PlayerModel> parent,EntityModelSet models){super(parent);banner=new BattleBannerEntityModel(models.bakeLayer(BattleBannerEntityModel.LAYER));}
 @SubscribeEvent public static void layers(EntityRenderersEvent.AddLayers event){for(var skin:event.getSkins()){var renderer=event.getPlayerRenderer(skin);if(renderer!=null)renderer.addLayer(new BackBannerLayer(renderer,event.getEntityModels()));}}
 public static boolean active(AvatarRenderState state){var level=Minecraft.getInstance().level;if(level==null||state.isInvisible||state.isSpectator)return false;var entity=level.getEntity(state.id);if(!(entity instanceof net.minecraft.world.entity.LivingEntity e)||!e.isAlive()||ClassStatusVisuals.concealed(e))return false;var data=EffectDetails.data(e);return data.has("banner_carrier")&&data.get("banner_carrier").getAsDouble()>level.getGameTime();}
 @Override public void submit(PoseStack pose,SubmitNodeCollector collector,int light,AvatarRenderState state,float yaw,float pitch){if(!active(state))return;pose.pushPose();getParentModel().body.translateAndRotate(pose);pose.translate(0,-.75,.35);pose.scale(1.15f,1.15f,1.15f);var visual=new BannerEntityRenderer.State();visual.ageInTicks=state.ageInTicks;visual.idleAnimationState.start(0);collector.submitModel(banner,visual,pose,banner.renderType(BannerEntityRenderer.TEXTURE),light,OverlayTexture.NO_OVERLAY,state.outlineColor,null);pose.popPose();}
}
